// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/Advertisers/{AccountSID}/Campaigns", wrapper.ListPrograms)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/Advertisers/{AccountSID}/Campaigns/{CampaignId}", wrapper.GetProgramById)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/Advertisers/{AccountSID}/MediaPartners", wrapper.ListPartners)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/Advertisers/{AccountSID}/MediaPartners/{PartnerId}", wrapper.GetPartnerById)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/Advertisers/{AccountSID}/Actions", wrapper.ListActions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/Advertisers/{AccountSID}/Actions/{ActionId}", wrapper.GetActionById)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/Advertisers/{AccountSID}/Actions/{ActionId}/Items", wrapper.ListActionItems)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/Advertisers/{AccountSID}/Conversions", wrapper.SubmitConversion)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/Advertisers/{AccountSID}/Campaigns/{CampaignId}/Notes", wrapper.ListNotes)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/Advertisers/{AccountSID}/Campaigns/{CampaignId}/Notes", wrapper.CreateNote)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/Advertisers/{AccountSID}/Campaigns/{CampaignId}/Notes/{NoteId}", wrapper.GetNoteById)

	return m
}

